import { fetchJson } from './facts'
import type { LonLat } from './coords'

/** Land borders as polylines of [lon, lat] points, each shared border listed once. */
export type BorderLinesData = LonLat[][]

interface BorderGeometry {
  type: 'LineString' | 'MultiLineString'
  coordinates: LonLat[] | LonLat[][]
}

let cached: Promise<BorderLinesData> | null = null

/** Loads the border lines once (generated by scripts/build-countries.mjs). */
export function loadBorders(): Promise<BorderLinesData> {
  cached ??= fetchJson<{ geometries: BorderGeometry[] }>('data/borders.json')
    .then(({ geometries }) =>
      geometries.flatMap((g) =>
        g.type === 'LineString' ? [g.coordinates as LonLat[]] : (g.coordinates as LonLat[][]),
      ),
    )
    .catch((error) => {
      // Let a later switch-on try again.
      cached = null
      throw error
    })
  return cached
}
